    표8_상담적용: [
        {"상황":"복음이 너무 추상적이거나 신화처럼 느껴지는 성도", "성경원리":"복음은 갈릴리, 유대라는 역사적 장소에서 일어난 사실이다. 역사적 증거들이 복음의 사실성을 지지한다(눅 1:1-4).", "실제적용":"복음의 역사적 증거를 다루는 변증학적 공부, 복음서 통독을 통한 예수님의 역사적 삶 이해"},
        {"상황":"전도할 때 어디서부터 시작해야 할지 모르는 성도", "성경원리":"베드로는 청중이 아는 것('너희도 알거니와')에서 시작했다. 상대방의 상황과 지식에서 복음 대화를 시작하라.", "실제적용":"전도 대화 훈련 — 상대방의 종교적·문화적 배경을 파악하고 그 지점에서 복음을 연결하는 방법"},
        {"상황":"신앙의 역사적 뿌리를 모르고 현재 경험만 중시하는 성도", "성경원리":"복음은 역사적 연속성 안에서 이해된다. 구약 → 요한 → 예수님 → 우리까지 이어지는 구속사의 흐름을 알아야 한다.", "실제적용":"구속사 성경 공부, 성경 전체의 흐름을 이해하는 구약-신약 연결 공부"}
    ],
    표9_교차참조: [
        {"구절":"마가복음 1:4-15", "연결점":"세례 요한의 세례 선포에서 예수님의 갈릴리 사역으로 — 구속사의 연결", "구분":"구약"},
        {"구절":"왕상 17:1-19:21", "연결점":"엘리야의 사역이 특정 장소에서 시작하여 확산됨 — 한 지점 시작 패턴", "구분":"구약"},
        {"구절":"이사야 9:1-2", "연결점":"갈릴리 사역에 대한 예언 — 어둠에 앉은 자들이 빛을 봄", "구분":"구약"},
        {"구절":"요한복음 1:46", "연결점":"나사렛에서 무슨 선한 것이 날 수 있냐 — 변방 갈릴리에서의 시작의 역설", "구분":"구약"},
        {"구절":"누가복음 1:1-4", "연결점":"눈으로 본 목격자들에서 시작한 복음의 역사성 강조", "구분":"신약"},
        {"구절":"고린도전서 15:3-8", "연결점":"복음의 역사적 사실 — 죽음, 장사, 부활, 나타나심", "구분":"신약"},
        {"구절":"요한복음 20:30-31", "연결점":"이 일들이 기록된 것은 믿음을 위함 — 역사적 증거와 믿음의 관계", "구분":"신약"},
        {"구절":"사도행전 1:8", "연결점":"예루살렘에서 시작하여 땅 끝까지 — 갈릴리→유대→세계의 확산 패턴", "구분":"신약"}
    ]
