    표8_상담적용: [
        {"상황":"자신이 너무 더러워 용서받을 수 없다고 생각하는 성도", "성경원리":"하나님이 깨끗케 하신 것을 속되다 하지 말라. 하나님은 모든 죄인을 정결케 하실 수 있다 (행 11:9, 요일 1:7)", "실제적용":"하나님의 용서가 자신에게도 적용됨을 성경으로 확신시키고 과거의 죄에서 자유로워지도록 인도하라"},
        {"상황":"다른 사람을 쉽게 판단하고 정죄하는 성도", "성경원리":"하나님이 정결케 하신 것을 속되다 하지 말라. 타인을 판단하는 것은 하나님의 주권을 침범하는 것이다 (행 11:9, 롬 14:3-4)", "실제적용":"판단의 기준을 하나님의 말씀으로 교체하고 타인을 대하는 태도를 성경적으로 교정하도록 도우라"},
        {"상황":"복음의 보편성을 믿지 않는 성도", "성경원리":"하나님은 이방인도 깨끗케 하실 수 있다. 복음은 모든 민족에게 열려 있다 (행 11:9, 요 3:16)", "실제적용":"복음의 보편적 능력을 성경으로 확신시키고 다양한 배경의 사람들에게 복음을 전하는 선교적 마음을 갖도록 격려하라"}
    ],
    표9_교차참조: [
        {"구절":"사 1:18", "연결점":"주홍 같이 붉은 죄도 눈같이 희어질 것이라는 하나님의 정결 선언", "구분":"구약"},
        {"구절":"겔 36:25", "연결점":"맑은 물로 뿌려 모든 더러운 것을 정결케 하겠다는 새 언약의 예언", "구분":"구약"},
        {"구절":"슥 13:1", "연결점":"죄와 더러움을 씻는 샘이 열린다는 메시아 예언", "구분":"구약"},
        {"구절":"왕하 5:14", "연결점":"이방인 나아만이 요단강에서 정결케 된 것은 하나님이 이방인도 정결케 하실 수 있음의 구약 사례", "구분":"구약"},
        {"구절":"막 7:15-19", "연결점":"예수님이 음식이 사람을 더럽히지 않는다고 선언하심으로 음식 정결법을 폐지하신 직접적 말씀", "구분":"신약"},
        {"구절":"요일 1:7", "연결점":"예수님의 피가 모든 죄에서 정결케 한다는 선언은 하나님의 정결케 하시는 역사의 신약적 완성", "구분":"신약"},
        {"구절":"롬 14:14", "연결점":"주 예수 안에서 어떤 것도 본래 부정한 것이 없다는 바울의 선언", "구분":"신약"},
        {"구절":"히 9:14", "연결점":"그리스도의 피가 우리의 양심을 죽은 행실에서 깨끗케 하신다는 선언", "구분":"신약"}
    ]
